import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/211第二百一十一章 善生尊者.md","filePath":"meditation/巴利文大藏经/211第二百一十一章 善生尊者.md"}'),o={name:"meditation/巴利文大藏经/211第二百一十一章 善生尊者.md"};function n(r,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a("<p>第二百一十一章 善生尊者</p><p>完全读懂巴利文大藏经</p><p>相应部21相应5经/善生经(比丘相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，善生尊者去见佛陀，佛陀远远的看见善生尊者向他走来，就对出家弟子们说：“弟子们，这位善生尊者有两个地方是值得赞叹的，第一个是他的相貌庄严、身材高大，他的行为端正有礼。第二个是他已经除灭了一切的烦恼和痛苦，证悟了解脱的果位。他之所以出家修行，就是为了灭除一切的烦恼和痛苦，从生死轮回中解脱出来，并由此证悟解脱的果位，达到不生不灭涅槃的境界。</p><p>善生尊者相貌庄严、身材高大，他的行为端正有礼，他的内心正直。世间一切的事物已经无法束缚捆绑他，他已经从世间一切的事物中解脱出来，他已经除灭一切的烦恼和痛苦，他已经不会再挂念和执着世间一切的事物，他已经不会再执着和挂念一切喜怒哀乐等等的念想，他已经征服战胜了欲望的魔军。这是他最后一世出生在世间，他这一世之后不会再投生在世间，不会再生死轮了。”</p><p>这时，佛陀说偈言：</p><p>「善生实端严，</p><p>具端正之心。</p><p>离结且离恼，</p><p>离缚无执着，</p><p>灭欲胜魔军，</p><p>住为最后身。」</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>",13)]))}const f=t(o,[["render",n]]);export{l as __pageData,f as default};
